/**
 * THROWAWAY measurement probe for the native-list-decoration investigation.
 * Not a regression spec: it asserts nothing, it measures. Dumps JSON to
 * `.obsidian-cache/list-geometry-probe.json` for offline analysis.
 */

import * as fsp from 'node:fs/promises';
import * as path from 'node:path';
import { browser } from '@wdio/globals';
import { obsidianPage } from 'wdio-obsidian-service';
import * as h from '../helpers.js';

const OUT = path.join(process.cwd(), '.obsidian-cache', 'list-geometry-probe.json');

const TAB = '\t';
const FIXTURES: Record<string, string> = {
  'tab-pure': ['- l1', `${TAB}- l2`, `${TAB}${TAB}- l3`, `${TAB}${TAB}${TAB}- l4`, ''].join('\n'),
  'sp4-pure': ['- l1', '    - l2', '        - l3', '            - l4', ''].join('\n'),
  'sp2-pure': ['- l1', '  - l2', '    - l3', '      - l4', ''].join('\n'),
  'tab-under-heading': ['# Section', '', '- l1', `${TAB}- l2`, `${TAB}${TAB}- l3`, ''].join('\n'),
  'kinds-at-depth': [
    '# Section',
    '',
    'A paragraph child.',
    '',
    '- a list item child',
    '',
    '> a quote child',
    '',
    '```',
    'code child',
    '```',
    '',
  ].join('\n'),
  'continuation': [
    '- alpha',
    `${TAB}continues here`,
    '1. one',
    `${TAB}cont of one`,
    '10. ten',
    `${TAB}cont of ten`,
    '',
  ].join('\n'),
  'ordered-tab': ['1. one', `${TAB}1. nested`, `${TAB}${TAB}1. deeper`, ''].join('\n'),
};

/** Measure everything about the currently open note's rendered lines. */
function measure(): Promise<unknown> {
  return browser.executeObsidian(({ app, obsidian }) => {
    const view = app.workspace.getActiveViewOfType(obsidian.MarkdownView);
    if (!view) throw new Error('no active markdown view');
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const cm = (view.editor as any).cm;
    const content: HTMLElement = cm.contentDOM;
    const base = content.getBoundingClientRect().left;
    const r = (el: Element | null) => {
      if (!el) return null;
      const b = el.getBoundingClientRect();
      return { l: +(b.left - base).toFixed(2), w: +b.width.toFixed(2), h: +b.height.toFixed(2) };
    };
    const cs = (el: Element | null, props: string[]) => {
      if (!el) return null;
      const s = getComputedStyle(el);
      const out: Record<string, string> = {};
      for (const p of props) out[p] = s.getPropertyValue(p);
      return out;
    };
    const pseudo = (el: Element | null, which: string, props: string[]) => {
      if (!el) return null;
      const s = getComputedStyle(el, which);
      const out: Record<string, string> = {};
      for (const p of props) out[p] = s.getPropertyValue(p);
      return out;
    };

    const rootVars = (() => {
      const s = getComputedStyle(content);
      const names = [
        '--list-indent',
        '--indent-size',
        '--indent-unit',
        '--list-indent-editing',
        '--list-indent-source',
        '--list-padding-inline-start',
        '--list-marker-space',
        '--list-spacing',
        '--list-bullet-size',
        '--list-bullet-radius',
        '--list-marker-color',
        '--list-bullet-end-padding',
        '--indentation-guide-width',
        '--indentation-guide-color',
        '--indentation-guide-width-active',
        '--indentation-guide-color-active',
        '--indentation-guide-editing-indent',
        '--to-decor-unit',
        '--to-marker-gutter',
        '--font-text-size',
      ];
      const out: Record<string, string> = {};
      for (const n of names) out[n] = s.getPropertyValue(n).trim();
      return out;
    })();

    const lines: unknown[] = [];
    for (const child of Array.from(content.children)) {
      let lineNo = -1;
      try {
        lineNo = cm.state.doc.lineAt(cm.posAtDOM(child)).number - 1;
      } catch {
        continue;
      }
      const el = child as HTMLElement;
      const docLine = cm.state.doc.line(lineNo + 1);
      const text: string = docLine.text;
      const ws = /^[\s>]*/.exec(text)?.[0] ?? '';
      const indents = Array.from(el.querySelectorAll(':scope .cm-indent'));
      const spacings = Array.from(el.querySelectorAll(':scope .cm-indent-spacing'));
      const hmdIndent = el.querySelector(':scope > .cm-hmd-list-indent');
      const fmtList = el.querySelector(':scope .cm-formatting-list');
      const bullet = el.querySelector(':scope .list-bullet');
      const listNum = el.querySelector(':scope .list-number');
      // where the caret sits at the first content character
      const contentCh = (() => {
        const m = /^[ \t]*(?:[-+*]|\d{1,9}[.)])[ \t]+/.exec(text);
        return m ? m[0].length : ws.length;
      })();
      let caretX: number | null = null;
      try {
        const c = cm.coordsAtPos(docLine.from + contentCh, -1);
        caretX = c ? +(c.left - base).toFixed(2) : null;
      } catch {
        caretX = null;
      }
      lines.push({
        n: lineNo,
        text,
        cls: el.className,
        rect: r(el),
        style: cs(el, [
          'padding-left',
          'margin-left',
          'text-indent',
          'tab-size',
          'padding-top',
          'padding-bottom',
        ]),
        caretX,
        hmdIndent: hmdIndent
          ? { rect: r(hmdIndent), style: cs(hmdIndent, ['width', 'display', 'white-space', 'padding-inline-start']) }
          : null,
        indents: indents.map((i) => ({
          rect: r(i),
          cls: i.className,
          style: cs(i, ['min-width', 'width', 'display']),
          before: pseudo(i, '::before', [
            'border-inline-end-width',
            'border-inline-end-color',
            'margin-inline-start',
            'width',
          ]),
        })),
        spacings: spacings.map((i) => ({ rect: r(i), style: cs(i, ['padding-inline-start']) })),
        fmtList: fmtList
          ? {
              rect: r(fmtList),
              cls: fmtList.className,
              style: cs(fmtList, ['padding-inline-start', 'padding-right', 'margin-right', 'white-space']),
            }
          : null,
        bullet: bullet
          ? {
              rect: r(bullet),
              style: cs(bullet, ['display', 'width']),
              after: pseudo(bullet, '::after', ['width', 'height', 'background-color', 'border-radius', 'left']),
            }
          : null,
        listNum: listNum ? { rect: r(listNum), style: cs(listNum, ['width']) } : null,
      });
    }
    return { rootVars, lines };
  });
}

/** Inject (or replace) a probe stylesheet. */
function injectCss(css: string): Promise<void> {
  return browser.execute((css) => {
    let el = document.getElementById('to-probe-style');
    if (!el) {
      el = document.createElement('style');
      el.id = 'to-probe-style';
      document.head.appendChild(el);
    }
    el.textContent = css;
  }, css);
}

function setConfig(key: string, value: unknown): Promise<void> {
  return browser.executeObsidian(
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    ({ app }, key, value) => (app.vault as any).setConfig(key, value),
    key,
    value,
  );
}

/** Tag every list line with its own tree level, the way the plugin could. */
function tagLevels(): Promise<unknown> {
  return browser.executeObsidian(({ app, obsidian }) => {
    const view = app.workspace.getActiveViewOfType(obsidian.MarkdownView);
    if (!view) throw new Error('no active markdown view');
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const cm = (view.editor as any).cm;
    const content: HTMLElement = cm.contentDOM;
    const out: unknown[] = [];
    for (const child of Array.from(content.children)) {
      let lineNo = -1;
      try {
        lineNo = cm.state.doc.lineAt(cm.posAtDOM(child)).number - 1;
      } catch {
        continue;
      }
      const el = child as HTMLElement;
      const text: string = cm.state.doc.line(lineNo + 1).text;
      const m = /^([ \t]*)([-+*]|\d{1,9}[.)])([ \t]+)/.exec(text);
      if (!m) continue;
      // Tree level from the raw whitespace, tab OR any space count.
      const ws = m[1];
      const level = ws.includes('\t') ? ws.length : Math.round(ws.length / (ws.length % 4 === 0 ? 4 : 2));
      el.style.setProperty('--probe-level', String(level));
    }
    return out;
  });
}

describe('PROBE: native list geometry', function () {
  const results: Record<string, unknown> = {};

  before(async function () {
    await obsidianPage.resetVault();
    await h.resetPluginState();
    await h.pinPositionIndicatorsOff();
  });

  after(async function () {
    await fsp.writeFile(OUT, JSON.stringify(results, null, 1));
    await injectCss('');
  });

  it('measures every fixture, mode off then on', async function () {
    for (const [label, md] of Object.entries(FIXTURES)) {
      const note = `Scratch/probe-${label}.md`;
      await h.createNote(note, md);
      await browser.pause(120);
      results[`${label}::off`] = await measure();
      if (!(await h.isOutlineMode(note))) {
        await h.toggleOutlineMode();
        await h.waitForNotice('Outline mode on');
        await h.dismissNotices();
      }
      await browser.pause(150);
      results[`${label}::on`] = await measure();
    }
  });

  it('E1: --list-indent override retargets native list columns', async function () {
    await injectCss('.markdown-source-view { --list-indent: 24px; }');
    for (const label of ['tab-pure', 'sp4-pure', 'sp2-pure', 'ordered-tab']) {
      const note = `Scratch/probe-${label}.md`;
      await h.openNote(note);
      await browser.pause(200);
      results[`E1-${label}`] = await measure();
    }
    await injectCss('');
  });

  it('E2: explicit width on .cm-hmd-list-indent normalizes any indentation style', async function () {
    await injectCss(`
      .markdown-source-view.mod-cm6 .cm-content > .cm-line .cm-hmd-list-indent {
        width: calc(var(--probe-level, 0) * 24px) !important;
        min-width: 0 !important;
        overflow: hidden;
      }
      .markdown-source-view.mod-cm6 .cm-content > .cm-line .cm-indent {
        min-width: 0 !important;
      }
    `);
    for (const label of ['tab-pure', 'sp4-pure', 'sp2-pure', 'continuation']) {
      const note = `Scratch/probe-${label}.md`;
      await h.openNote(note);
      await browser.pause(200);
      await tagLevels();
      await browser.pause(120);
      results[`E2-${label}`] = await measure();
    }
    await injectCss('');
  });

  it('E3: native indentation guides with the setting on and off', async function () {
    const note = 'Scratch/probe-tab-pure.md';
    for (const on of [true, false]) {
      await setConfig('showIndentGuide', on);
      await h.openNote(note);
      await browser.pause(250);
      results[`E3-showIndentGuide-${String(on)}`] = await measure();
    }
    await setConfig('showIndentGuide', true);
  });

  it('E4: caret placement survives a collapsed indent span', async function () {
    await injectCss(`
      .markdown-source-view.mod-cm6 .cm-content > .cm-line .cm-hmd-list-indent {
        width: calc(var(--probe-level, 0) * 24px) !important;
        min-width: 0 !important;
        overflow: hidden;
      }
      .markdown-source-view.mod-cm6 .cm-content > .cm-line .cm-indent { min-width: 0 !important; }
    `);
    await h.openNote('Scratch/probe-sp2-pure.md');
    await browser.pause(200);
    await tagLevels();
    await browser.pause(150);
    results['E4-clickmap'] = await browser.executeObsidian(({ app, obsidian }) => {
      const view = app.workspace.getActiveViewOfType(obsidian.MarkdownView);
      if (!view) throw new Error('no active markdown view');
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      const cm = (view.editor as any).cm;
      const out: unknown[] = [];
      for (let n = 1; n <= cm.state.doc.lines; n++) {
        const line = cm.state.doc.line(n);
        if (!line.text.trim()) continue;
        const probes: unknown[] = [];
        for (let ch = 0; ch <= line.text.length; ch++) {
          const c = cm.coordsAtPos(line.from + ch, -1);
          if (!c) continue;
          const back = cm.posAtCoords({ x: c.left + 1, y: (c.top + c.bottom) / 2 });
          probes.push({ ch, x: +c.left.toFixed(1), roundTrip: back === null ? null : back - line.from });
        }
        out.push({ n: n - 1, text: line.text, probes });
      }
      return out;
    });
    await injectCss('');
  });
});
