/**
 * THROWAWAY probe round 2 — override levers for native list geometry.
 * Asserts nothing; dumps JSON for offline analysis.
 */

import * as fsp from 'node:fs/promises';
import * as path from 'node:path';
import { browser } from '@wdio/globals';
import { obsidianPage } from 'wdio-obsidian-service';
import * as h from '../helpers.js';

const OUT = path.join(process.cwd(), '.probe-out', 'list-override-probe.json');
const TAB = '\t';

const LONG = 'wrapped '.repeat(24).trim();

const FIXTURES: Record<string, string> = {
  'tab-pure': ['- l1', `${TAB}- l2`, `${TAB}${TAB}- l3`, `${TAB}${TAB}${TAB}- l4`, ''].join('\n'),
  'sp4-pure': ['- l1', '    - l2', '        - l3', '            - l4', ''].join('\n'),
  'sp2-pure': ['- l1', '  - l2', '    - l3', '      - l4', ''].join('\n'),
  'wrap': ['- l1', `${TAB}- l2`, `${TAB}${TAB}- ${LONG}`, ''].join('\n'),
  'depth1-kinds': [
    '# Section',
    '',
    '- a list item child',
    '',
    'A paragraph sibling of the list.',
    '',
    '> a quote sibling',
    '',
    '```',
    'code sibling',
    '```',
    '',
  ].join('\n'),
  'nested-render': [
    '> [!note] Callout',
    '> - inside a callout',
    '>     - nested inside a callout',
    '',
    '- quoted list host',
    '',
  ].join('\n'),
  'fold-and-task': [
    '- parent with children',
    `${TAB}- child`,
    '- [ ] a task item',
    `${TAB}- [x] nested done`,
    '',
  ].join('\n'),
};

function measure(): Promise<unknown> {
  return browser.executeObsidian(({ app, obsidian }) => {
    const view = app.workspace.getActiveViewOfType(obsidian.MarkdownView);
    if (!view) throw new Error('no active markdown view');
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const cm = (view.editor as any).cm;
    const content: HTMLElement = cm.contentDOM;
    const base = content.getBoundingClientRect().left;
    const r = (el: Element | null) => {
      if (!el) return null;
      const b = el.getBoundingClientRect();
      return { l: +(b.left - base).toFixed(2), w: +b.width.toFixed(2), h: +b.height.toFixed(2) };
    };
    const rows: unknown[] = [];
    for (const child of Array.from(content.children)) {
      let lineNo = -1;
      try {
        lineNo = cm.state.doc.lineAt(cm.posAtDOM(child)).number - 1;
      } catch {
        continue;
      }
      const el = child as HTMLElement;
      const docLine = cm.state.doc.line(lineNo + 1);
      const text: string = docLine.text;
      const s = getComputedStyle(el);
      const m = /^[ \t]*(?:[-+*]|\d{1,9}[.)])[ \t]+(?:\[[ xX]\][ \t]+)?/.exec(text);
      const contentCh = m ? m[0].length : (/^[\s>]*/.exec(text)?.[0].length ?? 0);
      const coord = (ch: number, side: -1 | 1) => {
        try {
          const c = cm.coordsAtPos(docLine.from + ch, side);
          return c ? { x: +(c.left - base).toFixed(2), top: +c.top.toFixed(1) } : null;
        } catch {
          return null;
        }
      };
      // rects of every client rect of the line's text — reveals soft-wrap rows
      const rowTops = Array.from(el.getClientRects()).map((b) => +b.top.toFixed(1));
      rows.push({
        n: lineNo,
        text,
        cls: el.className,
        inlineStyle: el.getAttribute('style'),
        rect: r(el),
        pad: s.paddingLeft,
        mar: s.marginLeft,
        ti: s.textIndent,
        padTop: s.paddingTop,
        padBottom: s.paddingBottom,
        tabSize: s.tabSize,
        contentStart: coord(contentCh, -1),
        lineEnd: coord(text.length, -1),
        hmdIndentW: (() => {
          const e2 = el.querySelector(':scope > .cm-hmd-list-indent');
          return e2 ? r(e2) : null;
        })(),
        nIndent: el.querySelectorAll(':scope .cm-indent').length,
        activeIndents: Array.from(el.querySelectorAll(':scope .cm-active-indent')).map((e2) => r(e2)),
        fmtList: (() => {
          const e2 = el.querySelector(':scope .cm-formatting-list');
          return e2 ? { rect: r(e2), pis: getComputedStyle(e2).paddingInlineStart } : null;
        })(),
        bullet: (() => {
          const e2 = el.querySelector(':scope .list-bullet');
          if (!e2) return null;
          const a = getComputedStyle(e2, '::after');
          return { rect: r(e2), w: a.width, h: a.height, radius: a.borderRadius, bg: a.backgroundColor };
        })(),
        rowTops,
        // rendered (non-source) list inside a callout/embed, if any
        renderedList: (() => {
          const li = el.querySelector('.markdown-rendered li');
          return li ? r(li) : null;
        })(),
      });
    }
    return rows;
  });
}

function injectCss(css: string): Promise<void> {
  return browser.execute((css) => {
    let el = document.getElementById('to-probe-style');
    if (!el) {
      el = document.createElement('style');
      el.id = 'to-probe-style';
      document.head.appendChild(el);
    }
    el.textContent = css;
  }, css);
}

function setConfig(key: string, value: unknown): Promise<void> {
  return browser.executeObsidian(
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    ({ app }, key, value) => (app.vault as any).setConfig(key, value),
    key,
    value,
  );
}

function tagLevels(): Promise<void> {
  return browser.executeObsidian(({ app, obsidian }) => {
    const view = app.workspace.getActiveViewOfType(obsidian.MarkdownView);
    if (!view) throw new Error('no active markdown view');
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const cm = (view.editor as any).cm;
    const content: HTMLElement = cm.contentDOM;
    for (const child of Array.from(content.children)) {
      let lineNo = -1;
      try {
        lineNo = cm.state.doc.lineAt(cm.posAtDOM(child)).number - 1;
      } catch {
        continue;
      }
      const el = child as HTMLElement;
      const text: string = cm.state.doc.line(lineNo + 1).text;
      const m = /^([ \t]*)(?:[-+*]|\d{1,9}[.)])[ \t]+/.exec(text);
      if (!m) continue;
