/** Register a CM6 extension that replaces list leading whitespace with a sized widget. */
function installWidgetExtension(unit: number): Promise<string> {
  return browser.executeObsidian(({ app, obsidian }, unit) => {
    const view = app.workspace.getActiveViewOfType(obsidian.MarkdownView);
    if (!view) throw new Error('no active markdown view');
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const cm = (view.editor as any).cm;
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const req = (window as any).require as ((id: string) => any) | undefined;
    if (!req) return 'no require';
    let V: any, S: any;
    try {
      V = req('@codemirror/view');
      S = req('@codemirror/state');
    } catch (e) {
      return 'require failed: ' + String(e);
    }
    if (!V?.Decoration || !S?.StateEffect) return 'missing exports';
    class IndentWidget extends V.WidgetType {
      constructor(readonly px: number) {
        super();
      }
      eq(o: any) {
        return o.px === this.px;
      }
      toDOM() {
        const span = document.createElement('span');
        span.className = 'to-probe-indent';
        span.style.display = 'inline-block';
        span.style.width = this.px + 'px';
        span.style.height = '1px';
        return span;
      }
      ignoreEvent() {
        return false;
      }
    }
    const build = (v: any) => {
      const b = new (S.RangeSetBuilder ?? V.RangeSetBuilder)();
      for (const { from, to } of v.visibleRanges) {
        let pos = from;
        while (pos <= to) {
          const line = v.state.doc.lineAt(pos);
          const m = /^([ \t]*)(?:[-+*]|\d{1,9}[.)])[ \t]+/.exec(line.text);
          if (m && m[1].length > 0) {
            const ws: string = m[1];
            const level = ws.includes('\t') ? ws.length : Math.round(ws.length / 2);
            b.add(
              line.from,
              line.from + ws.length,
              V.Decoration.replace({ widget: new IndentWidget(level * unit) }),
            );
          }
          pos = line.to + 1;
        }
      }
      return b.finish();
    };
    const plugin = V.ViewPlugin.fromClass(
      class {
        decorations: any;
        constructor(v: any) {
          this.decorations = build(v);
        }
        update(u: any) {
          if (u.docChanged || u.viewportChanged) this.decorations = build(u.view);
        }
      },
      { decorations: (p: any) => p.decorations },
    );
    cm.dispatch({ effects: S.StateEffect.appendConfig.of([plugin]) });
    return 'ok';
  }, unit);
}

