/** THROWAWAY probe — can the list variables be scoped to our own per-line class? */

import * as fsp from 'node:fs/promises';
import * as path from 'node:path';
import { browser } from '@wdio/globals';
import { obsidianPage } from 'wdio-obsidian-service';
import * as h from '../helpers.js';

const OUT = path.join(process.cwd(), '.probe-out', 'list-scope-probe.json');
const TAB = '\t';
const MD = ['# Section', '', '- l1', `${TAB}- l2`, `${TAB}${TAB}- l3`, '', '  continuation-ish', ''].join('\n');

const SCOPED = `
  .markdown-source-view.mod-cm6 .cm-content > .cm-line.to-decor-list {
    --list-indent: 1.5rem;
    --indentation-guide-editing-indent: 0px;
    --list-padding-inline-start: 0.75em;
  }
`;

function injectCss(css: string): Promise<void> {
  return browser.execute((css) => {
    let el = document.getElementById('to-probe-style');
    if (!el) {
      el = document.createElement('style');
      el.id = 'to-probe-style';
      document.head.appendChild(el);
    }
    el.textContent = css;
  }, css);
}

function measure(): Promise<unknown> {
  return browser.executeObsidian(({ app, obsidian }) => {
    const view = app.workspace.getActiveViewOfType(obsidian.MarkdownView);
    if (!view) throw new Error('no active markdown view');
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const cm = (view.editor as any).cm;
    const content: HTMLElement = cm.contentDOM;
    const base = content.getBoundingClientRect().left;
    const rl = (el: Element | null) => (el ? +(el.getBoundingClientRect().left - base).toFixed(2) : null);
    return Array.from(content.children).map((child) => {
      const el = child as HTMLElement;
      let n = -1;
      try {
        n = cm.state.doc.lineAt(cm.posAtDOM(child)).number - 1;
      } catch {
        return null;
      }
      const s = getComputedStyle(el);
      return {
        n,
        text: cm.state.doc.line(n + 1).text,
        cls: el.className,
        rect: +(el.getBoundingClientRect().left - base).toFixed(2),
        pad: s.paddingLeft,
        mar: s.marginLeft,
        tabSize: s.tabSize,
        listIndent: s.getPropertyValue('--list-indent').trim(),
        bulletL: rl(el.querySelector(':scope .list-bullet')),
        guideXs: Array.from(el.querySelectorAll(':scope .cm-indent')).map((e2) => {
          const b = e2.getBoundingClientRect();
          const p = getComputedStyle(e2, '::before');
          return +(b.left - base + (parseFloat(p.marginInlineStart) || 0)).toFixed(2);
        }),
      };
    });
  });
}

describe('PROBE: per-line scoping of the list variables', function () {
  const results: Record<string, unknown> = {};

  before(async function () {
    await obsidianPage.resetVault();
    await h.resetPluginState();
    await h.pinPositionIndicatorsOff();
    await h.createNote('Scratch/scope-on.md', MD);
    await h.createNote('Scratch/scope-off.md', MD);
  });

  after(async function () {
    await fsp.mkdir(path.dirname(OUT), { recursive: true });
    await fsp.writeFile(OUT, JSON.stringify(results, null, 1));
    await injectCss('');
  });

  it('scoped to .to-decor-list: on-mode note changes, off-mode note does not', async function () {
    await injectCss(SCOPED);
    await browser.executeObsidian(({ app }) => app.workspace.detachLeavesOfType('markdown'));

    await h.openNote('Scratch/scope-on.md');
    await browser.pause(300);
    if (!(await h.isOutlineMode('Scratch/scope-on.md'))) {
      await h.toggleOutlineMode();
      await h.waitForNotice('Outline mode on');
      await h.dismissNotices();
    }
    await browser.pause(300);
    results['scoped-on'] = await measure();

    await h.openNote('Scratch/scope-off.md');
    await browser.pause(300);
    results['scoped-off'] = await measure();

    // reopen the on-note from scratch so the hang measures with the CSS live
    await browser.executeObsidian(({ app }) => app.workspace.detachLeavesOfType('markdown'));
    await h.openNote('Scratch/scope-on.md');
    await browser.pause(400);
    results['scoped-on-fresh'] = await measure();
  });
});
