/** THROWAWAY: staleness on a plain mode toggle, hang ownership, bullet weight, list trail. */

import * as fsp from 'node:fs/promises';
import * as path from 'node:path';
import { browser } from '@wdio/globals';
import { obsidianPage } from 'wdio-obsidian-service';
import * as h from '../helpers.js';

const OUT = path.join(process.cwd(), '.probe-out', 'final.json');
const DIR = path.join(process.cwd(), '.probe-out', 'final-shots');
const NOTE = 'Notes/List decoration demo.md';

function setLayout(v: string): Promise<void> {
  return browser.executeObsidian(
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    ({ plugins }, v) => (plugins.trueOutliner as any).setListLayout(v) as Promise<void>,
    v,
  );
}
function setBullet(v: string): Promise<void> {
  return browser.executeObsidian(
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    ({ plugins }, v) => (plugins.trueOutliner as any).setListBullet(v) as Promise<void>,
    v,
  );
}
function injectCss(css: string): Promise<void> {
  return browser.execute((css) => {
    let el = document.getElementById('to-probe-style');
    if (!el) {
      el = document.createElement('style');
      el.id = 'to-probe-style';
      document.head.appendChild(el);
    }
    el.textContent = css;
  }, css);
}

/** Wrapped-row start vs the item's own content column, for wrapping list lines. */
function wrapCheck(): Promise<unknown> {
  return browser.executeObsidian(({ app, obsidian }) => {
    const view = app.workspace.getActiveViewOfType(obsidian.MarkdownView);
    if (!view) throw new Error('no view');
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const cm = (view.editor as any).cm;
    const content: HTMLElement = cm.contentDOM;
    const base = content.getBoundingClientRect().left;
    const rows: unknown[] = [];
    for (const child of Array.from(content.children)) {
      const el = child as HTMLElement;
      if (!el.classList.contains('to-decor-list')) continue;
      let n = -1;
      try {
        n = cm.state.doc.lineAt(cm.posAtDOM(el)).number - 1;
      } catch {
        continue;
      }
      const line = cm.state.doc.line(n + 1);
      const m = /^[ \t]*(?:[-+*]|\d{1,9}[.)])[ \t]+/.exec(line.text);
      const c = cm.coordsAtPos(line.from + (m ? m[0].length : 0), -1);
      const range = document.createRange();
      const walker = document.createTreeWalker(el, NodeFilter.SHOW_TEXT);
      const tops = new Map<number, number>();
      let node: Node | null = walker.nextNode();
      while (node) {
        range.selectNodeContents(node);
        for (const b of Array.from(range.getClientRects())) {
          const k = Math.round(b.top);
          const l = +(b.left - base).toFixed(1);
          if (!tops.has(k) || l < (tops.get(k) as number)) tops.set(k, l);
        }
        node = walker.nextNode();
      }
      const starts = Array.from(tops.entries()).sort((a, b) => a[0] - b[0]).map((e) => e[1]);
      if (starts.length < 2) continue;
      const s = getComputedStyle(el);
      rows.push({
        n,
        text: line.text.trim().slice(0, 24),
        pad: s.paddingLeft,
        contentX: c ? +(c.left - base).toFixed(1) : null,
        wrapX: starts[1],
      });
    }
    return rows;
  });
}

async function freshOpen(mode: 'on' | 'off'): Promise<void> {
  await browser.executeObsidian(({ app }) => app.workspace.detachLeavesOfType('markdown'));
  await h.openNote(NOTE);
  await browser.pause(400);
  const on = await h.isOutlineMode(NOTE);
  if ((mode === 'on') !== on) {
    await h.toggleOutlineMode();
    await browser.pause(300);
    await h.dismissNotices();
  }
  await browser.pause(300);
}

/* Own the hang: the content column of a list item under `column` bullets is
 * `depth * unit + gutter` absolutely; relative to the line's own box (shifted
 * by supplementalDepth * unit) that is `(depth - supp) * unit + gutter`. */
const OWN_HANG_CSS = `
  .markdown-source-view.mod-cm6 .cm-content > .cm-line.to-list-grid.to-list-bullet-column {
    --to-list-hang: calc(
      (var(--to-depth, 0) - var(--to-supp-depth, 0)) * var(--to-decor-unit, 1.5rem)
      + var(--to-marker-gutter, 1.25rem)
    );
    padding-inline-start: var(--to-list-hang) !important;
    text-indent: calc(-1 * var(--to-list-hang)) !important;
  }
`;

describe('PROBE: final questions', function () {
  const results: Record<string, unknown> = {};

  before(async function () {
    await obsidianPage.resetVault();
    await h.resetPluginState();
    await fsp.mkdir(DIR, { recursive: true });
    await setLayout('own-guides');
    await setBullet('column');
  });

  after(async function () {
    await fsp.mkdir(path.dirname(OUT), { recursive: true });
    await fsp.writeFile(OUT, JSON.stringify(results, null, 1));
    await injectCss('');
    await setLayout('native');
    await setBullet('native');
  });

  it('A: is the hang stale after a plain outline-mode toggle?', async function () {
    await freshOpen('off');
    results['A1-fresh-off'] = await wrapCheck();
    await h.toggleOutlineMode();
    await browser.pause(500);
    await h.dismissNotices();
    results['A2-toggled-on'] = await wrapCheck();
    await freshOpen('on');
    results['A3-fresh-on'] = await wrapCheck();
  });

  it('B: does owning the hang remove the dependency?', async function () {
    await injectCss(OWN_HANG_CSS);
