/** THROWAWAY: exactly where the bullet sits relative to its guide column and its row. */

import * as fsp from 'node:fs/promises';
import * as path from 'node:path';
import { browser } from '@wdio/globals';
import { obsidianPage } from 'wdio-obsidian-service';
import * as h from '../helpers.js';

const OUT = path.join(process.cwd(), '.probe-out', 'bullet-align.json');
const NOTE = 'Notes/List decoration demo.md';

function set(key: 'listLayout' | 'listBullet', v: string): Promise<void> {
  return browser.executeObsidian(
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    ({ plugins }, key, v) => {
      const p = plugins.trueOutliner as any;
      return (key === 'listLayout' ? p.setListLayout(v) : p.setListBullet(v)) as Promise<void>;
    },
    key,
    v,
  );
}

describe('PROBE: bullet alignment', function () {
  const results: Record<string, unknown> = {};

  before(async function () {
    await obsidianPage.resetVault();
    await h.resetPluginState();
    await set('listLayout', 'own-guides');
    await set('listBullet', 'column');
  });

  after(async function () {
    await fsp.mkdir(path.dirname(OUT), { recursive: true });
    await fsp.writeFile(OUT, JSON.stringify(results, null, 1));
    await set('listLayout', 'native');
    await set('listBullet', 'native');
  });

  it('measures bullet centre against the guide column and the row', async function () {
    await browser.executeObsidian(({ app }) => app.workspace.detachLeavesOfType('markdown'));
    await h.openNote(NOTE);
    await browser.pause(500);
    if (!(await h.isOutlineMode(NOTE))) {
      await h.toggleOutlineMode();
      await browser.pause(300);
      await h.dismissNotices();
    }
    await browser.pause(400);

    results.rows = await browser.executeObsidian(({ app, obsidian }) => {
      const view = app.workspace.getActiveViewOfType(obsidian.MarkdownView);
      if (!view) throw new Error('no view');
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      const cm = (view.editor as any).cm;
      const content: HTMLElement = cm.contentDOM;
      const cb = content.getBoundingClientRect();
      const unit = parseFloat(getComputedStyle(content).fontSize) * 1.5; // 1.5rem at 16px root
      const rootPx = parseFloat(getComputedStyle(document.documentElement).fontSize);
      const out: unknown[] = [];
      for (const child of Array.from(content.children)) {
        const el = child as HTMLElement;
        let n = -1;
        try {
          n = cm.state.doc.lineAt(cm.posAtDOM(el)).number - 1;
        } catch {
          continue;
        }
        if (n > 14) continue;
        const es = getComputedStyle(el);
        const er = el.getBoundingClientRect();
        const isList = el.classList.contains('to-decor-list');
        const bullet = el.querySelector(':scope .list-bullet');
        const icon = el.querySelector(':scope .to-decor-marker-icon');
        // the ::after is the visible dot; measure it via its own layout box
        const dot = bullet
          ? (() => {
              const a = getComputedStyle(bullet, '::after');
              const br = bullet.getBoundingClientRect();
              return {
                bulletBoxLeft: +(br.left - cb.left).toFixed(2),
                bulletBoxTop: +(br.top - cb.top).toFixed(2),
                bulletBoxW: +br.width.toFixed(2),
                bulletBoxH: +br.height.toFixed(2),
                afterW: a.width,
                afterH: a.height,
                afterLeft: a.left,
                afterTop: a.top,
                lineHeight: getComputedStyle(bullet).lineHeight,
                display: getComputedStyle(bullet).display,
                alignItems: getComputedStyle(bullet).alignItems,
              };
            })()
          : null;
        const iconRect = icon
          ? (() => {
              const r = icon.getBoundingClientRect();
              return {
                left: +(r.left - cb.left).toFixed(2),
                top: +(r.top - cb.top).toFixed(2),
                w: +r.width.toFixed(2),
                h: +r.height.toFixed(2),
                centreX: +(r.left - cb.left + r.width / 2).toFixed(2),
                centreY: +(r.top - cb.top + r.height / 2).toFixed(2),
              };
            })()
          : null;
        // first text row of the line, for a row-centre reference
        let textTop: number | null = null;
        let textBottom: number | null = null;
        {
          const range = document.createRange();
          const walker = document.createTreeWalker(el, NodeFilter.SHOW_TEXT);
          let node: Node | null = walker.nextNode();
          while (node) {
            if (!node.parentElement?.closest('.cm-formatting-list, .cm-hmd-list-indent')) {
              range.selectNodeContents(node);
              const rects = Array.from(range.getClientRects()).filter((b) => b.width > 0);
              if (rects.length) {
                textTop = +(rects[0]!.top - cb.top).toFixed(2);
                textBottom = +(rects[0]!.bottom - cb.top).toFixed(2);
                break;
              }
            }
            node = walker.nextNode();
          }
        }
        out.push({
          n,
          text: cm.state.doc.line(n + 1).text.trim().slice(0, 22),
          isList,
          unit,
          rootPx,
          depth: es.getPropertyValue('--to-depth').trim(),
          lineTop: +(er.top - cb.top).toFixed(2),
          lineH: +er.height.toFixed(2),
          padTop: es.paddingTop,
          textTop,
          textBottom,
          dot,
          iconRect,
        });
      }
      return out;
    });
  });
});
