cat > e2e/specs/97-task-column-probe.e2e.ts <<'TS'
/** THROWAWAY: does the bullet-column setting move a task checkbox? */

import * as fsp from 'node:fs/promises';
import * as path from 'node:path';
import { browser } from '@wdio/globals';
import { obsidianPage } from 'wdio-obsidian-service';
import * as h from '../helpers.js';

const OUT = path.join(process.cwd(), '.probe-out', 'task-column.json');
const NOTE = 'Notes/List decoration demo.md';

function set(key: 'listLayout' | 'listBullet', v: string): Promise<void> {
  return browser.executeObsidian(
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    ({ plugins }, key, v) => {
      const p = plugins.trueOutliner as any;
      return (key === 'listLayout' ? p.setListLayout(v) : p.setListBullet(v)) as Promise<void>;
    },
    key,
    v,
  );
}

function measure(): Promise<unknown> {
  return browser.executeObsidian(({ app, obsidian }) => {
    const view = app.workspace.getActiveViewOfType(obsidian.MarkdownView);
    if (!view) throw new Error('no view');
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const cm = (view.editor as any).cm;
    const content: HTMLElement = cm.contentDOM;
    const base = content.getBoundingClientRect().left;
    const out: unknown[] = [];
    for (const child of Array.from(content.children)) {
      const el = child as HTMLElement;
      if (!el.classList.contains('to-decor-list')) continue;
      let n = -1;
      try {
        n = cm.state.doc.lineAt(cm.posAtDOM(el)).number - 1;
      } catch {
        continue;
      }
      const text: string = cm.state.doc.line(n + 1).text;
      const isTask = /^[ \t]*(?:[-+*]|\d{1,9}[.)])[ \t]+\[[ xX]\]/.test(text);
      if (!isTask && !/^[ \t]*[-+*][ \t]+\S/.test(text)) continue;
      const es = getComputedStyle(el);
      const depth = Number(es.getPropertyValue('--to-depth').trim() || 0);
      const fmt = el.querySelector(':scope .cm-formatting-list') as HTMLElement | null;
      const cbox = el.querySelector(':scope input[type="checkbox"], :scope .task-list-item-checkbox') as HTMLElement | null;
      const bullet = el.querySelector(':scope .list-bullet') as HTMLElement | null;
      const L = (e: Element | null) => (e ? +(e.getBoundingClientRect().left - base).toFixed(2) : null);
      const W = (e: Element | null) => (e ? +e.getBoundingClientRect().width.toFixed(2) : null);
      out.push({
        n,
        text: text.trim().slice(0, 26),
        isTask,
        depth,
        column: depth * 24,
        pis: fmt ? getComputedStyle(fmt).paddingInlineStart : null,
        fmtL: L(fmt),
        checkboxL: L(cbox),
        checkboxW: W(cbox),
        bulletL: L(bullet),
      });
    }
    return out;
  });
}

describe('PROBE: task lines under bullet-column', function () {
  const results: Record<string, unknown> = {};

  before(async function () {
    await obsidianPage.resetVault();
    await h.resetPluginState();
    await set('listLayout', 'own-guides');
  });

  after(async function () {
    await fsp.mkdir(path.dirname(OUT), { recursive: true });
    await fsp.writeFile(OUT, JSON.stringify(results, null, 1));
    await set('listLayout', 'native');
    await set('listBullet', 'native');
  });

  it('compares native vs column bullets on task and bullet lines', async function () {
    for (const bullet of ['native', 'column']) {
      await set('listBullet', bullet);
      await browser.executeObsidian(({ app }) => app.workspace.detachLeavesOfType('markdown'));
      await h.openNote(NOTE);
      await browser.pause(500);
      if (!(await h.isOutlineMode(NOTE))) {
        await h.toggleOutlineMode();
        await browser.pause(300);
        await h.dismissNotices();
      }
      await browser.pause(400);
      results[bullet] = await measure();
    }
  });
});
