# --- 1. compute the depths once per line; short-circuit hasOverlay on the trail ---
old = """function activeGuideDepths(guide: LineGuideFact, layout: ListLayout): readonly number[] {
  if (layout !== 'own-guides' || guide.listGuideDepths.length === 0) return guide.guideDepths;
  return [...guide.guideDepths, ...guide.listGuideDepths].sort((a, b) => a - b);
