/** THROWAWAY: verify the grid, the hang, and the marker anchors. */
import * as fsp from 'node:fs/promises';
import * as path from 'node:path';
import { browser } from '@wdio/globals';
import { obsidianPage } from 'wdio-obsidian-service';
import * as h from '../helpers.js';

const OUT = path.join(process.cwd(), '.probe-out', 'grid.json');
const NOTE = 'Notes/List decoration demo.md';

function measure(): Promise<unknown> {
  return browser.executeObsidian(({ app, obsidian }) => {
    const view = app.workspace.getActiveViewOfType(obsidian.MarkdownView);
    if (!view) throw new Error('no view');
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const cm = (view.editor as any).cm;
    const content: HTMLElement = cm.contentDOM;
    const cb = content.getBoundingClientRect();
    const unit = parseFloat(getComputedStyle(content).getPropertyValue('--to-decor-unit')) || 0;
    const rows: unknown[] = [];
    for (const child of Array.from(content.children)) {
      const el = child as HTMLElement;
      let n = -1;
      try {
        n = cm.state.doc.lineAt(cm.posAtDOM(el)).number - 1;
      } catch {
        continue;
      }
      const text: string = cm.state.doc.line(n + 1).text;
      const es = getComputedStyle(el);
      const isList = el.classList.contains('to-decor-list');
      const depth = Number(es.getPropertyValue('--to-depth').trim() || 0);
      // first text row outside the marker/indent chrome
      let textX: number | null = null;
      let textTop: number | null = null;
      let textBottom: number | null = null;
      let wrapX: number | null = null;
      {
        const range = document.createRange();
        const walker = document.createTreeWalker(el, NodeFilter.SHOW_TEXT);
        const tops = new Map<number, number>();
        let node: Node | null = walker.nextNode();
        while (node) {
          if (!node.parentElement?.closest('.cm-formatting-list, .cm-hmd-list-indent')) {
            range.selectNodeContents(node);
            for (const b of Array.from(range.getClientRects())) {
              if (b.width === 0) continue;
              const k = Math.round(b.top);
              const l = +(b.left - cb.left).toFixed(2);
              if (!tops.has(k) || l < (tops.get(k) as number)) tops.set(k, l);
              if (textTop === null || b.top < textTop + cb.top) {
                textTop = +(b.top - cb.top).toFixed(2);
                textBottom = +(b.bottom - cb.top).toFixed(2);
              }
            }
          }
          node = walker.nextNode();
        }
        const sorted = Array.from(tops.entries()).sort((a, b) => a[0] - b[0]);
        textX = sorted.length ? sorted[0]![1] : null;
        wrapX = sorted.length > 1 ? sorted[1]![1] : null;
      }
      const centre = (e: Element | null) => {
        if (!e) return null;
        const r = e.getBoundingClientRect();
        return { x: +(r.left - cb.left + r.width / 2).toFixed(2), y: +(r.top - cb.top + r.height / 2).toFixed(2) };
      };
      const bulletEl = el.querySelector(':scope .list-bullet');
      const bulletDot = bulletEl
        ? (() => {
            const a = getComputedStyle(bulletEl, '::after');
            const br = bulletEl.getBoundingClientRect();
            const w = parseFloat(a.width) || 0;
            const hgt = parseFloat(a.height) || 0;
            const l = parseFloat(a.left) || 0;
            const t = parseFloat(a.top) || 0;
            return {
              x: +(br.left - cb.left + l + w / 2).toFixed(2),
              y: +(br.top - cb.top + t + hgt / 2).toFixed(2),
              size: +w.toFixed(2),
            };
          })()
        : null;
      rows.push({
        n,
        text: text.trim().slice(0, 26),
        isList,
        depth,
        column: +(depth * unit).toFixed(2),
        pad: es.paddingLeft,
        ti: es.textIndent,
        mar: es.marginLeft,
        textX,
        wrapX,
        textTop,
        textBottom,
        icon: centre(el.querySelector(':scope .to-decor-marker-icon')),
        bulletDot,
        checkbox: centre(el.querySelector(':scope input[type="checkbox"], :scope .task-list-item-checkbox')),
        nIndentGuide: el.querySelectorAll(':scope .cm-indent').length,
        nativeGuideW: (() => {
          const i = el.querySelector(':scope .cm-indent');
          return i ? getComputedStyle(i, '::before').borderInlineEndWidth : null;
        })(),
      });
    }
    return { unit, rows };
  });
}

describe('PROBE: the grid after implementation', function () {
  const results: Record<string, unknown> = {};
  before(async function () {
    await obsidianPage.resetVault();
    await h.resetPluginState();
  });
  after(async function () {
    await fsp.mkdir(path.dirname(OUT), { recursive: true });
    await fsp.writeFile(OUT, JSON.stringify(results, null, 1));
  });

  it('measures the demo note, mode on', async function () {
    await browser.executeObsidian(({ app }) => app.workspace.detachLeavesOfType('markdown'));
    await h.openNote(NOTE);
    await browser.pause(500);
    if (!(await h.isOutlineMode(NOTE))) {
      await h.toggleOutlineMode();
      await browser.pause(300);
      await h.dismissNotices();
    }
    await browser.pause(400);
    results.freshOn = await measure();

    // and after toggling mode on for an already-open note, the stale-hang case
    await h.toggleOutlineMode();
    await browser.pause(300);
    await h.toggleOutlineMode();
    await browser.pause(500);
    await h.dismissNotices();
    results.toggled = await measure();
  });
});
