cat > e2e/specs/56-list-grid.e2e.ts <<'TS'
/**
 * lists-on-the-outline-grid: the geometry assertions.
 *
 * Everything here measures RENDERED positions rather than the custom properties
 * that produce them — the layer's whole history is of computations that were
 * internally consistent and rendered wrong. Columns are read from the elements
 * Obsidian actually draws, and text columns from the text nodes' own client
 * rects rather than through `coordsAtPos`, which reports the end of a marker's
 * TEXT rather than of its box and so agrees with a wrong answer.
 */

import { browser, expect } from '@wdio/globals';
import { obsidianPage } from 'wdio-obsidian-service';
import * as h from '../helpers.js';
import { LIST_GRID_MD, LIST_GRID_NOTE } from '../fixtures/decorations.js';

interface LineGeometry {
  n: number;
  text: string;
  isList: boolean;
  depth: number;
  /** The depth column this line's markers and guides should use. */
  column: number;
  /** Left edge of the line's own text, outside any marker/indent chrome. */
  textX: number | null;
  /** Left edge of the second visual row, when the line soft-wraps. */
  wrapX: number | null;
  /** Centre of a synthetic marker or a bullet dot; left edge of a checkbox. */
  markerX: number | null;
  guideColumns: number[];
  nativeGuideWidth: string | null;
}

function geometry(): Promise<LineGeometry[]> {
  return browser.executeObsidian(({ app, obsidian }) => {
    const view = app.workspace.getActiveViewOfType(obsidian.MarkdownView);
    if (!view) throw new Error('no active markdown view');
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const cm = (view.editor as any).cm;
    const content: HTMLElement = cm.contentDOM;
    const cb = content.getBoundingClientRect();
    const remPx = parseFloat(getComputedStyle(document.documentElement).fontSize);
    const unitRaw = getComputedStyle(content).getPropertyValue('--to-decor-unit').trim();
    const unit = parseFloat(unitRaw) * (unitRaw.endsWith('rem') ? remPx : 1);
    const out: LineGeometry[] = [];
    for (const child of Array.from(content.children)) {
      const el = child as HTMLElement;
      let n = -1;
      try {
        n = cm.state.doc.lineAt(cm.posAtDOM(el)).number - 1;
      } catch {
        continue;
      }
      const es = getComputedStyle(el);
      const depth = Number(es.getPropertyValue('--to-depth').trim() || '0');

      // Text rows, skipping the marker and indent chrome.
      const range = document.createRange();
      const walker = document.createTreeWalker(el, NodeFilter.SHOW_TEXT);
      const rowLefts = new Map<number, number>();
      let node: Node | null = walker.nextNode();
      while (node) {
        const chrome = node.parentElement?.closest(
          '.cm-formatting-list, .cm-hmd-list-indent, .task-list-label',
        );
        if (!chrome) {
          range.selectNodeContents(node);
          for (const b of Array.from(range.getClientRects())) {
            if (b.width === 0) continue;
            const key = Math.round(b.top);
            const left = +(b.left - cb.left).toFixed(2);
            if (!rowLefts.has(key) || left < (rowLefts.get(key) as number)) {
              rowLefts.set(key, left);
            }
          }
        }
        node = walker.nextNode();
      }
      const rows = Array.from(rowLefts.entries())
        .sort((a, b) => a[0] - b[0])
        .map((e) => e[1]);

      const bullet = el.querySelector(':scope .list-bullet');
      const icon = el.querySelector(':scope .to-decor-marker-icon');
      const checkbox = el.querySelector(':scope .task-list-item-checkbox');
      let markerX: number | null = null;
      if (bullet) {
        const after = getComputedStyle(bullet, '::after');
        const br = bullet.getBoundingClientRect();
        markerX = +(
          br.left -
          cb.left +
          (parseFloat(after.left) || 0) +
          (parseFloat(after.width) || 0) / 2
        ).toFixed(2);
      } else if (icon) {
        const r = icon.getBoundingClientRect();
        markerX = +(r.left - cb.left + r.width / 2).toFixed(2);
      } else if (checkbox) {
        markerX = +(checkbox.getBoundingClientRect().left - cb.left).toFixed(2);
      }

      const indents = Array.from(el.querySelectorAll(':scope .cm-indent'));
      out.push({
        n,
        text: cm.state.doc.line(n + 1).text.trim().slice(0, 40),
        isList: el.classList.contains('to-decor-list'),
        depth,
        column: +(depth * unit).toFixed(2),
        textX: rows.length ? rows[0]! : null,
        wrapX: rows.length > 1 ? rows[1]! : null,
        markerX,
        guideColumns: [],
        nativeGuideWidth: indents.length
          ? getComputedStyle(indents[0]!, '::before').borderInlineEndWidth
          : null,
      });
    }
    return out;
  });
}

async function open(): Promise<LineGeometry[]> {
  await h.createNote(LIST_GRID_NOTE, LIST_GRID_MD);
  if (!(await h.isOutlineMode(LIST_GRID_NOTE))) {
    await h.toggleOutlineMode();
    await h.waitForNotice('Outline mode on');
    await h.dismissNotices();
  }
  await browser.pause(300);
  return geometry();
}

const find = (rows: LineGeometry[], text: string): LineGeometry => {
  const row = rows.find((r) => r.text.startsWith(text));
  if (!row) throw new Error(`no line starting "${text}" — have ${rows.map((r) => r.text)}`);
  return row;
};

const GUTTER = 20; // 1.25rem at a 16px root

describe('lists on the outline grid', function () {
  let rows: LineGeometry[];

  before(async function () {
    await obsidianPage.resetVault();
    await h.resetPluginState();
    await h.pinPositionIndicatorsOff();
    rows = await open();
  });

  afterEach(async function () {
    await h.dismissNotices();
  });

  it('steps every tab-indented list level by exactly one unit', async function () {
    const one = find(rows, 'one');
    const two = find(rows, '- two');
    const three = find(rows, '- three');
    expect(two.column - one.column).toBe(24);
    expect(three.column - two.column).toBe(24);
    // and the RENDERED marker follows the computed column, not just the fact
    expect(two.markerX).toBeCloseTo(two.column, 1);
    expect(three.markerX).toBeCloseTo(three.column, 1);
  });

  it('puts a list marker on its own depth column, like every other kind', async function () {
    for (const row of rows) {
      if (row.markerX === null) continue;
      if (row.text.startsWith('[')) continue; // checkbox: start, not centre — below
      expect(
        Math.abs(row.markerX - row.column),
        `marker for ${JSON.stringify(row.text)} at ${row.markerX}, column ${row.column}`,
      ).toBeLessThan(0.5);
    }
  });

  it('starts every kind’s text one marker gutter right of its own column', async function () {
    for (const row of rows) {
      if (row.textX === null) continue;
      if (row.text.startsWith('10.')) continue; // wider than the gutter — its own case
      expect(
        row.textX - row.column,
        `text for ${JSON.stringify(row.text)} at ${row.textX}, column ${row.column}`,
      ).toBeCloseTo(GUTTER, 1);
    }
  });

  it('aligns a heading, a paragraph and a list item at the same depth', async function () {
    const paragraph = find(rows, 'This paragraph owns');
    const item = find(rows, '- child of the paragraph');
    // The item is the paragraph's child (the attachment rule), so one deeper.
    expect(item.column - paragraph.column).toBe(24);
    expect(item.textX! - item.column).toBeCloseTo(GUTTER, 1);
    expect(paragraph.textX! - paragraph.column).toBeCloseTo(GUTTER, 1);
  });

  it('lands a soft-wrapped list row on its own item’s text column', async function () {
    for (const row of rows) {
      if (row.wrapX === null) continue;
      expect(row.wrapX, `wrap for ${JSON.stringify(row.text)}`).toBeCloseTo(row.textX!, 1);
    }
  });

  it('starts a task checkbox on the column and its text at the gutter', async function () {
    const open = rows.find((r) => r.text.startsWith('[ ]'));
    const done = rows.find((r) => r.text.startsWith('[x]'));
    for (const row of [open, done]) {
      if (!row) continue;
      expect(row.markerX).toBeCloseTo(row.column, 1);
      expect(row.textX! - row.column).toBeCloseTo(GUTTER, 1);
    }
  });

  it('pushes a wide ordered marker’s own text out rather than crossing the column', async function () {
    const ninth = find(rows, '9. ninth');
    const tenth = find(rows, '10. tenth');
    expect(tenth.column).toBe(ninth.column);
    expect(tenth.textX!).toBeGreaterThan(ninth.textX!);
    expect(tenth.textX! - tenth.column).toBeGreaterThan(GUTTER);
  });

  it('suppresses Obsidian’s own list guide, leaving exactly one line per level', async function () {
    for (const row of rows) {
      if (row.nativeGuideWidth === null) continue;
      expect(row.nativeGuideWidth, `native guide on ${JSON.stringify(row.text)}`).toBe('0px');
    }
  });

  it('draws our own guide on list levels, one layer per ancestor', async function () {
    const two = find(rows, '- two');
    const three = find(rows, '- three');
    const bg2 = await h.getLinePseudoComputedStyle(two.n, 'background-image');
    const bg3 = await h.getLinePseudoComputedStyle(three.n, 'background-image');
    const layers = (s: string) => (s.match(/gradient\(/g) ?? []).length;
    expect(layers(bg3)).toBe(layers(bg2) + 1);
  });

  it('renders a note without outline mode exactly as stock, with one open beside it', async function () {
    const stock = 'Scratch/list-grid-stock.md';
    await h.createNote(stock, LIST_GRID_MD);
    await browser.pause(250);
    const off = await geometry();
    for (const row of off) {
      // No decoration class means no contribution: the fact-derived column is
      // 0 for every line and nothing was moved onto a grid.
      expect(row.isList).toBe(false);
      expect(row.column).toBe(0);
    }
  });
});
