/** THROWAWAY: ordered markers and fold chevrons against the column. */
import * as fsp from 'node:fs/promises';
import * as path from 'node:path';
import { browser } from '@wdio/globals';
import { obsidianPage } from 'wdio-obsidian-service';
import * as h from '../helpers.js';
const DIR = path.join(process.cwd(), '.probe-out', 'p');
const NOTE = 'Scratch/ord-fold.md';
const MD = [
  '# H',
  '',
  '- a bullet with children',
  '\t- child',
  '- [ ] a task with children',
  '\t- child',
  '1. first',
  '\t1. child',
  '9. ninth',
  '10. tenth',
  '100. hundredth',
  '',
].join('\n');

describe('PROBE', function () {
  before(async function () {
    await obsidianPage.resetVault();
    await h.resetPluginState();
    await h.pinPositionIndicatorsOff();
    await fsp.mkdir(DIR, { recursive: true });
  });
  it('measures', async function () {
    await h.createNote(NOTE, MD);
    if (!(await h.isOutlineMode(NOTE))) {
      await h.toggleOutlineMode();
      await browser.pause(250);
      await h.dismissNotices();
    }
    await h.setCursor(0, 0);
    await browser.pause(400);
    await h.screenshotFull(DIR, 'shot');
    const dump = await browser.executeObsidian(({ app, obsidian }) => {
      const view = app.workspace.getActiveViewOfType(obsidian.MarkdownView)!;
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      const cm = (view.editor as any).cm;
      const content: HTMLElement = cm.contentDOM;
      const cb = content.getBoundingClientRect();
      const remPx = parseFloat(getComputedStyle(document.documentElement).fontSize);
      const unit = parseFloat(getComputedStyle(content).getPropertyValue('--to-decor-unit')) * remPx;
      const box = (e: Element | null) => {
        if (!e) return null;
        const r = e.getBoundingClientRect();
        return { l: +(r.left - cb.left).toFixed(2), r: +(r.right - cb.left).toFixed(2), w: +r.width.toFixed(2) };
      };
      const out: unknown[] = [];
      for (const child of Array.from(content.children)) {
        const el = child as HTMLElement;
        let n = -1;
        try { n = cm.state.doc.lineAt(cm.posAtDOM(el)).number - 1; } catch { continue; }
        const text: string = cm.state.doc.line(n + 1).text;
        if (!text.trim() || text.startsWith('#')) continue;
        const es = getComputedStyle(el);
        const depth = Number(es.getPropertyValue('--to-depth').trim() || '0');
        const bullet = el.querySelector(':scope .list-bullet');
        let dot = null;
        if (bullet) {
          const a = getComputedStyle(bullet, '::after');
          const br = bullet.getBoundingClientRect();
          const w = parseFloat(a.width) || 0;
          dot = { c: +(br.left - cb.left + (parseFloat(a.left) || 0) + w / 2).toFixed(2), w: +w.toFixed(2) };
        }
        out.push({
          n,
          text: text.trim().slice(0, 24),
          column: +(depth * unit).toFixed(2),
          fmtList: box(el.querySelector(':scope .cm-formatting-list')),
          fmtOl: box(el.querySelector(':scope .cm-formatting-list-ol')),
          dot,
          checkbox: box(el.querySelector(':scope .task-list-item-checkbox')),
          foldWrapper: box(el.querySelector(':scope .cm-fold-indicator')),
          foldGlyph: box(el.querySelector(':scope .collapse-indicator')),
          bulletEndPad: getComputedStyle(el).getPropertyValue('--list-bullet-end-padding'),
        });
      }
      return out;
    });
    await fsp.writeFile(path.join(DIR, 'dump.json'), JSON.stringify(dump, null, 1));
  });
});
