/** TEMPORARY probe — measurements + screenshots for the visual review. Not committed. */
import { browser } from '@wdio/globals';
import { obsidianPage } from 'wdio-obsidian-service';
import * as h from '../helpers.js';

function probe(): Promise<unknown> {
  return browser.executeObsidian(({ app, obsidian }) => {
    const view = app.workspace.getActiveViewOfType(obsidian.MarkdownView);
    if (!view) throw new Error('no view');
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const cm = (view.editor as any).cm;
    const content: HTMLElement = cm.contentDOM;
    const cb = content.getBoundingClientRect();
    const rem = parseFloat(getComputedStyle(document.documentElement).fontSize);
    const uRaw = getComputedStyle(content).getPropertyValue('--to-decor-unit').trim();
    const unit = parseFloat(uRaw) * (uRaw.endsWith('rem') ? rem : 1);
    const rx = (r: DOMRect) => ({ l: +(r.left - cb.left).toFixed(2), r: +(r.right - cb.left).toFixed(2), t: +r.top.toFixed(2), b: +r.bottom.toFixed(2) });
    const out: Record<string, unknown>[] = [];
    for (const child of Array.from(content.children)) {
      const el = child as HTMLElement;
      let n = -1;
      try { n = cm.state.doc.lineAt(cm.posAtDOM(el)).number - 1; } catch { continue; }
      const es = getComputedStyle(el);
      const depth = Number(es.getPropertyValue('--to-depth').trim() || '0');
      const supp = Number(es.getPropertyValue('--to-supp-depth').trim() || '0');
      const q = (sel: string) => { const e = el.querySelector(sel) as HTMLElement | null; return e ? rx(e.getBoundingClientRect()) : null; };
      // first text-node run of the ACTUAL content (after the marker span)
      const walker = document.createTreeWalker(el, NodeFilter.SHOW_TEXT);
      const runs: { text: string; box: ReturnType<typeof rx> }[] = [];
      let t: Node | null;
      while ((t = walker.nextNode())) {
        const s = t.nodeValue ?? '';
        if (!s) continue;
        const range = document.createRange();
        range.selectNodeContents(t);
        const r = range.getBoundingClientRect();
        if (r.width === 0 && r.height === 0) continue;
        runs.push({ text: JSON.stringify(s.slice(0, 18)), box: rx(r) });
      }
      const indents = Array.from(el.querySelectorAll(':scope > .cm-indent')) as HTMLElement[];
      out.push({
        n,
        raw: JSON.stringify(cm.state.doc.line(n + 1).text.slice(0, 34)),
        cls: Array.from(el.classList).filter((c) => c.startsWith('to-decor') || c.includes('task') || c.includes('HyperMD-list')).join(' '),
        depth, supp, column: +(depth * unit).toFixed(2),
        indentSpans: indents.length,
        indentW: indents.map((i) => +i.getBoundingClientRect().width.toFixed(2)),
        bullet: q('.list-bullet'),
        bulletAfterX: (() => { const e = el.querySelector('.list-bullet'); if (!e) return null; const cs = getComputedStyle(e, '::after'); return { w: cs.width, h: cs.height }; })(),
        ol: q('.cm-formatting-list-ol'),
        cbox: q('.task-list-item-checkbox'),
        label: q('.task-list-label'),
        icon: q('.to-decor-marker-icon'),
        fold: q('.cm-fold-indicator .collapse-indicator'),
        runs,
      });
    }
    return { unit, rem, out };
  });
}

