    const view = app.workspace.getActiveViewOfType(obsidian.MarkdownView);
    if (!view) throw new Error('no view');
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const cm = (view.editor as any).cm;
    const content: HTMLElement = cm.contentDOM;
    const cb = content.getBoundingClientRect();
    const px = (v: number) => +(v - cb.left).toFixed(2);
    const out: Record<string, unknown>[] = [];
    for (const child of Array.from(content.children)) {
      const el = child as HTMLElement;
      let n = -1;
      try { n = cm.state.doc.lineAt(cm.posAtDOM(el)).number - 1; } catch { continue; }
      const es = getComputedStyle(el);
      const depth = Number(es.getPropertyValue('--to-depth').trim() || '0');
      const supp = Number(es.getPropertyValue('--to-supp-depth').trim() || '0');
      // flat walk of the line's inline children, with tag/class/rect
      const parts: string[] = [];
      const walk = (node: Node, path: string) => {
        for (const c of Array.from(node.childNodes)) {
          if (c.nodeType === 3) {
            const r = document.createRange(); r.selectNodeContents(c);
            const b = r.getBoundingClientRect();
            parts.push(`${path}#text ${JSON.stringify((c.nodeValue ?? '').slice(0, 14))} [${px(b.left)},${px(b.right)}]`);
          } else if (c.nodeType === 1) {
            const e = c as HTMLElement;
            const b = e.getBoundingClientRect();
            const tag = e.tagName.toLowerCase() + (e.className && typeof e.className === 'string' ? '.' + e.className.trim().split(/\s+/).join('.') : '');
            parts.push(`${path}<${tag}> [${px(b.left)},${px(b.right)}] w=${b.width.toFixed(2)}`);
            walk(e, path + '  ');
          }
        }
      };
      walk(el, '');
      out.push({ n, raw: JSON.stringify(cm.state.doc.line(n + 1).text.slice(0, 30)), depth, supp, parts });
    }
    return out;
  });
}

