/** TEMPORARY probe — not committed. */
import { browser } from '@wdio/globals';
import { obsidianPage } from 'wdio-obsidian-service';
import * as h from '../helpers.js';

const STAGE = process.env.PROBE_STAGE ?? 'after';

async function forceChevrons(): Promise<void> {
  await browser.executeObsidian(() => {
    let el = document.getElementById('probe-style');
    if (!el) { el = document.createElement('style'); el.id = 'probe-style'; document.head.appendChild(el); }
    el.textContent = `.cm-fold-indicator{opacity:1 !important} .collapse-indicator{opacity:1 !important}`;
  });
}

/** Preview of the task-text fix: pull the content span back by the measured space advance. */
async function previewTaskFix(on: boolean): Promise<number> {
  return browser.executeObsidian(({ app, obsidian }, enable: boolean) => {
    const view = app.workspace.getActiveViewOfType(obsidian.MarkdownView);
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const cm = (view!.editor as any).cm;
    const line = cm.contentDOM.querySelector('.HyperMD-task-line .cm-list-1, .HyperMD-task-line [class*="cm-list-"]') as HTMLElement | null;
    let adv = 0;
    if (line?.firstChild && line.firstChild.nodeType === 3) {
      const r = document.createRange();
      r.setStart(line.firstChild, 0);
      r.setEnd(line.firstChild, 1);
      adv = r.getBoundingClientRect().width;
    }
    let el = document.getElementById('probe-task-style');
    if (!el) { el = document.createElement('style'); el.id = 'probe-task-style'; document.head.appendChild(el); }
    el.textContent = enable && adv
      ? `.cm-line.to-decor-list.HyperMD-task-line > span[class*="cm-list-"]{margin-inline-start:-${adv}px}`
      : '';
    return +adv.toFixed(2);
  }, on);
}

function measure(): Promise<unknown[]> {
  return browser.executeObsidian(({ app, obsidian }) => {
    const view = app.workspace.getActiveViewOfType(obsidian.MarkdownView);
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const cm = (view!.editor as any).cm;
    const content: HTMLElement = cm.contentDOM;
    const cb = content.getBoundingClientRect();
    const px = (v: number) => +(v - cb.left).toFixed(2);
    const rem = parseFloat(getComputedStyle(document.documentElement).fontSize);
    const uRaw = getComputedStyle(content).getPropertyValue('--to-decor-unit').trim();
    const unit = parseFloat(uRaw) * (uRaw.endsWith('rem') ? rem : 1);
    return Array.from(content.children).map((child) => {
      const el = child as HTMLElement;
      const es = getComputedStyle(el);
      const d = Number(es.getPropertyValue('--to-depth').trim() || '0');
      const q = (sel: string) => { const e = el.querySelector(sel); return e ? px(e.getBoundingClientRect().left) : null; };
      const qr = (sel: string) => { const e = el.querySelector(sel); return e ? px(e.getBoundingClientRect().right) : null; };
      // first ink of the content span
      const cs = el.querySelector(':scope > span[class*="cm-list-"]:not(.cm-formatting)') as HTMLElement | null;
      let ink: number | null = null;
      if (cs) {
        const w = document.createTreeWalker(cs, NodeFilter.SHOW_TEXT);
        const t = w.nextNode();
        if (t) {
          const s = t.nodeValue ?? '';
          const i = s.search(/\S/);
          if (i >= 0) { const r = document.createRange(); r.setStart(t, i); r.setEnd(t, i + 1); ink = px(r.getBoundingClientRect().left); }
        }
      }
      return {
        t: (el.textContent ?? '').slice(0, 18),
        d, col: +(d * unit).toFixed(2),
        rows: el.getClientRects().length,
        h: +el.getBoundingClientRect().height.toFixed(1),
        bullet: q('.list-bullet'),
        ol: q('.cm-formatting-list-ol'),
        cbox: q('.task-list-item-checkbox'),
        icon: q('.to-decor-marker-icon'),
        chevR: qr('.cm-fold-indicator .collapse-indicator svg'),
        ink,
      };
    });
  });
}

