    const view = app.workspace.getActiveViewOfType(obsidian.MarkdownView)!;
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const cm = (view.editor as any).cm;
    const content: HTMLElement = cm.contentDOM;
    const cb = content.getBoundingClientRect();
    const px = (v: number) => +(v - cb.left).toFixed(2);
    return Array.from(content.children).map((child) => {
      const el = child as HTMLElement;
      const es = getComputedStyle(el);
      const wrap = el.querySelector('.cm-hmd-list-indent') as HTMLElement | null;
      // first ink
      let ink: number | null = null;
      const w = document.createTreeWalker(el, NodeFilter.SHOW_TEXT);
      let n: Node | null;
      while ((n = w.nextNode())) {
        if (n.parentElement?.closest('.cm-hmd-list-indent, .cm-formatting-list, .task-list-label')) continue;
        const s = n.nodeValue ?? '';
        const i = s.search(/\S/);
        if (i < 0) continue;
        const r = document.createRange(); r.setStart(n, i); r.setEnd(n, i + 1);
        ink = px(r.getBoundingClientRect().left);
        break;
      }
      return {
        raw: JSON.stringify(cm.state.doc.lineAt(cm.posAtDOM(el)).text.slice(0, 24)),
