/** TEMPORARY probe — not committed. */
import { browser } from '@wdio/globals';
import { obsidianPage } from 'wdio-obsidian-service';
import * as h from '../helpers.js';

function measure(): Promise<unknown> {
  return browser.executeObsidian(({ app, obsidian }) => {
    const view = app.workspace.getActiveViewOfType(obsidian.MarkdownView)!;
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const cm = (view.editor as any).cm;
    const content: HTMLElement = cm.contentDOM;
    const cb = content.getBoundingClientRect();
    const deadRight = getComputedStyle(cm.dom).getPropertyValue('--to-chevron-dead-right').trim();
    const rows = Array.from(content.children).map((child) => {
      const el = child as HTMLElement;
      const box = (sel: string) => {
        const e = el.querySelector(sel);
        if (!e) return null;
        const r = e.getBoundingClientRect();
        return { l: +(r.left - cb.left).toFixed(2), r: +(r.right - cb.left).toFixed(2), cy: +(r.top + r.height / 2).toFixed(2), h: +r.height.toFixed(2) };
      };
      const bullet = el.querySelector('.list-bullet');
      let bulletBox = null;
      if (bullet) {
        const after = getComputedStyle(bullet, '::after');
        const br = bullet.getBoundingClientRect();
        const ah = parseFloat(after.height) || 0;
        // the ::after is centred in the (zero-width, dot-tall) box
        bulletBox = { cy: +(br.top + br.height / 2).toFixed(2), h: ah };
      }
      return {
        t: (el.textContent ?? '').slice(0, 16),
        cls: Array.from(el.classList).filter((c) => c.startsWith('to-decor')).join(' '),
        icon: box(':scope > .to-decor-marker-icon svg'),
        bullet: bulletBox,
        cbox: box('.task-list-item-checkbox'),
        chevWrap: box('.cm-fold-indicator .collapse-indicator'),
        chevGlyph: box('.cm-fold-indicator .collapse-indicator svg'),
      };
    });
    return { deadRight, rows };
  });
}

let seq = 0;
async function open(md: string): Promise<void> {
  const note = `Scratch/chev-${++seq}.md`;
  await h.createNote(note, md);
  if (!(await h.isOutlineMode(note))) { await h.toggleOutlineMode(); await browser.pause(200); await h.dismissNotices(); }
  await browser.pause(400);
}

const show = (tag: string, v: any) => {
  console.log(`${tag} deadRight=${v.deadRight}`);
  for (const r of v.rows) {
    if (!r.t.trim()) continue;
    const anchor = r.icon ?? r.bullet ?? r.cbox;
    const d = anchor && r.chevGlyph ? (r.chevGlyph.cy - anchor.cy).toFixed(2) : '-';
    console.log(`${tag}   ${r.t.padEnd(16)} ${r.cls.padEnd(28)} anchorCy=${anchor ? anchor.cy : '-'} glyph=${r.chevGlyph ? `[${r.chevGlyph.l},${r.chevGlyph.r}] cy=${r.chevGlyph.cy} h=${r.chevGlyph.h}` : '-'} wrap=${r.chevWrap ? `[${r.chevWrap.l},${r.chevWrap.r}]` : '-'} dCy=${d}`);
  }
};

describe('probe', function () {
  before(async function () {
    await obsidianPage.resetVault();
    await h.resetPluginState();
    await h.pinPositionIndicatorsOff();
  });

  it('A: chevron vertical, heading first', async function () {
    await open(['# Heading', '', 'A paragraph with children.', '', '- a bullet', '\t- child', '', '- [ ] a task', '\t- [ ] child', ''].join('\n'));
    show('PA', await measure());
  });

  it('B: list foldable FIRST in the document', async function () {
    await open(['- a bullet', '\t- child', '', '# Heading', '', 'Body under the heading.', ''].join('\n'));
    show('PB', await measure());
  });
});
