/** TEMPORARY probe — not committed. */
import { browser } from '@wdio/globals';
import { obsidianPage } from 'wdio-obsidian-service';
import * as h from '../helpers.js';

function measure(): Promise<unknown> {
  return browser.executeObsidian(({ app, obsidian }) => {
    const view = app.workspace.getActiveViewOfType(obsidian.MarkdownView)!;
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const cm = (view.editor as any).cm;
    const content: HTMLElement = cm.contentDOM;
    return Array.from(content.children).map((child) => {
      const el = child as HTMLElement;
      const lr = el.getBoundingClientRect();
      const rel = (r: DOMRect) => ({ t: +(r.top - lr.top).toFixed(2), b: +(r.bottom - lr.top).toFixed(2), cy: +(r.top + r.height / 2 - lr.top).toFixed(2) });
      const of = (sel: string) => { const e = el.querySelector(sel); return e ? rel(e.getBoundingClientRect()) : null; };
      // the first ink run
      let text = null;
      const w = document.createTreeWalker(el, NodeFilter.SHOW_TEXT);
      let n: Node | null;
      while ((n = w.nextNode())) {
        const s = n.nodeValue ?? '';
        const i = s.search(/\S/);
        if (i < 0) continue;
        const r = document.createRange(); r.setStart(n, i); r.setEnd(n, s.length);
        const b = r.getBoundingClientRect();
        if (b.height === 0) continue;
        text = rel(b); break;
      }
      const ci = el.querySelector('.cm-fold-indicator .collapse-indicator') as HTMLElement | null;
      const cs = ci ? getComputedStyle(ci) : null;
      const es = getComputedStyle(el);
      return {
        t: (el.textContent ?? '').slice(0, 16),
        fs: es.fontSize, padT: es.paddingTop, lineH: +lr.height.toFixed(2),
        text,
        icon: of(':scope > .to-decor-marker-icon svg'),
        iconBox: of(':scope > .to-decor-marker-icon'),
        bullet: of('.list-bullet'),
        cbox: of('.task-list-item-checkbox'),
        fiWrap: of('.cm-fold-indicator'),
        chevBox: ci ? rel(ci.getBoundingClientRect()) : null,
        chevGlyph: of('.cm-fold-indicator .collapse-indicator svg'),
        chevCss: cs ? { pos: cs.position, top: cs.top, bottom: cs.bottom, h: cs.height, align: cs.alignItems, disp: cs.display } : null,
      };
    });
  });
}

let seq = 0;
async function open(md: string): Promise<void> {
  const note = `Scratch/cm-${++seq}.md`;
  await h.createNote(note, md);
  if (!(await h.isOutlineMode(note))) { await h.toggleOutlineMode(); await browser.pause(200); await h.dismissNotices(); }
  await browser.pause(400);
}

describe('probe', function () {
  before(async function () {
    await obsidianPage.resetVault();
    await h.resetPluginState();
    await h.pinPositionIndicatorsOff();
  });

  it('mechanism', async function () {
    await open(['# H1', '', 'body', '', '## H2', '', 'body2', '', 'A parent paragraph.', '', '\tchild', '', '- a bullet', '\t- child', '', '- [ ] a task', '\t- [ ] child', ''].join('\n'));
