/** TEMPORARY probe — not committed. */
import { browser } from '@wdio/globals';
import { obsidianPage } from 'wdio-obsidian-service';
import * as h from '../helpers.js';

function measure(): Promise<unknown> {
  return browser.executeObsidian(({ app, obsidian }) => {
    const view = app.workspace.getActiveViewOfType(obsidian.MarkdownView)!;
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const cm = (view.editor as any).cm;
    const content: HTMLElement = cm.contentDOM;
    const cb = content.getBoundingClientRect();
    const deadRight = getComputedStyle(cm.dom).getPropertyValue('--to-chevron-dead-right').trim();
    const rows = Array.from(content.children).map((child) => {
      const el = child as HTMLElement;
      const lr = el.getBoundingClientRect();
      const g = el.querySelector('.cm-fold-indicator .collapse-indicator svg');
      const m =
        el.querySelector(':scope > .to-decor-marker-icon svg') ??
        el.querySelector('.list-bullet') ??
        el.querySelector('.task-list-item-checkbox') ??
        el.querySelector('.cm-formatting-list-ol');
      if (!g || !m) return null;
      const gr = g.getBoundingClientRect();
      const mr = m.getBoundingClientRect();
      return {
        t: (el.textContent ?? '').slice(0, 18),
        dy: el.style.getPropertyValue('--to-chevron-dy') || '(none)',
        dCy: +(gr.top + gr.height / 2 - (mr.top + mr.height / 2)).toFixed(2),
        glyphL: +(gr.left - cb.left).toFixed(2),
        glyphR: +(gr.right - cb.left).toFixed(2),
        markerL: +(mr.left - cb.left).toFixed(2),
      };
    }).filter(Boolean);
    return { deadRight, rows };
  });
}

let seq = 0;
async function open(md: string): Promise<void> {
  const note = `Scratch/cf-${++seq}.md`;
  await h.createNote(note, md);
  if (!(await h.isOutlineMode(note))) { await h.toggleOutlineMode(); await browser.pause(200); await h.dismissNotices(); }
  await browser.pause(500);
}

const show = (tag: string, v: any) => {
  console.log(`${tag} deadRight=${v.deadRight}`);
  for (const r of v.rows) console.log(`${tag}  ${r.t.padEnd(18)} dy=${String(r.dy).padEnd(8)} residual=${String(r.dCy).padEnd(7)} glyph=[${r.glyphL},${r.glyphR}] markerL=${r.markerL}`);
};

describe('probe', function () {
  before(async function () {
    await obsidianPage.resetVault();
    await h.resetPluginState();
    await h.pinPositionIndicatorsOff();
  });

  it('all kinds, heading first', async function () {
    await open(['# H1', '', 'body', '', '## H2', '', 'body2', '', 'A parent paragraph.', '', '\tchild', '', '- a bullet', '\t- child', '', '1. a number', '\t1. child', '', '- [ ] a task', '\t- [ ] child', ''].join('\n'));
    show('PF', await measure());
  });

  it('list foldable FIRST — the glitch repro', async function () {
    await open(['- a bullet', '\t- child', '', '# Heading', '', 'Body under it.', '', '\tchild of body', ''].join('\n'));
    show('PG', await measure());
  });

  it('task foldable FIRST — the other dead-right value', async function () {
    await open(['- [ ] a task', '\t- [ ] child', '', '# Heading', '', 'Body under it.', '', '\tchild of body', ''].join('\n'));
    show('PT', await measure());
  });
});
